import pickle
from mpmath import mp, mpf, cos, pi, fabs, log10
mp.dps=1750
V=pickle.load(open("vals13.pkl","rb")); b1=mpf(V["b"][0])
r1=[-179432796080806181555764192681922, 16202391464697998676250059325083475143, 12175132950806329102539724551106424252, -5558967846293201450298059869636636192, -10129062916158719682644427368425182253, -4928249653257079101245839896895761521, 31711443824936882949130579162969778538]
x=[b1]+[cos(2*pi*j/13) for j in range(6)]
print("wrong-field 300dps relation residual at 1750 dps: 10^%.1f"%log10(fabs(sum(a*b for a,b in zip(r1,x)))))
r2=[35011495497426723661671025366386739, -5978614153950190812802965805425955960, -32290981083072833990756769133576765561, -26683134910136279564454406814803212230, -24798638218001389144658367398437657493, 1676928551074652969288218228756708349, -25877802537486262713293811280844261476, -22384634338276724077303584044664645781, 9182111363585763191531679282423765113, 14077884835835323231548627285631212178, -17766349482370914393890551536791880353, -3848760097604478684457574787144471414, -3527059467761090991626771567296445968]
x=[b1+mpf(10)**-300]+[cos(2*pi*j/52) for j in range(12)]
print("perturbed 600dps relation residual at 1750 dps: 10^%.1f"%log10(fabs(sum(a*b for a,b in zip(r2,x)))))
